# -*- coding: utf-8 -*-
# Сверка с ответами учебника Никольский 11: пересчитано вручную + SymPy (check_nk1.py), условия сверены со сканом (OCR mistral_193dfa3a536d5264).
KB = "ключ неверен (сверка с ответом учебника Никольский 11 и пересчёт вручную): "
QG = "в условии была искажена запись (сверено с учебником Никольский 11): "
SRC = "сверка с ответами учебника Никольский 11 25.09 + пересчёт вручную"
P = {}
OLD = lambda v, n: [(v, "прежний (неверный) ключ: " + n)]
P["G11_TB_13_5*_13_29_б"] = {"qrep": (r"\sqrt[4]{x", r"\sqrt[5]{x"), "k": r"$3$", "src": SRC, "dadd": OLD(r"$2$", "ответ соседнего пункта а)"),
  "why": QG + "первый корень пятой, а не четвёртой степени (№ 13.29 б); ключ 2 был ответом пункта а) — верный ответ 3: ⁵√32 + ∛64 = 2 + 4 = 6"}
P["G11_TB_11_3*_11_12_б"] = {"k": r"$(2 + \sqrt{3}; +\infty)$", "drop": [2], "src": SRC,
  "why": KB + "x ≥ 1/3 и x² − 4x + 1 > 0 ⇒ x > 2 + √3; в ключе был пустой «промежуток» [1; 2 − √3); вариант «[1/3; 2 − √3) ∪ (2 + √3; +∞)» равен ответу — закрыт"}
P["G11_TB_5_9_5_84_б"] = {"k": r"Наибольшее значение: $\dfrac{5}{4}$; наименьшее значение: $1$", "drop": [1], "src": SRC,
  "dadd": OLD(r"Наибольшее значение: $\dfrac{5}{4}$; наименьшего значения не существует", "не учтено f(0) = 1"),
  "why": KB + "f = 1 − x/(x² + 4) на (−∞; 0]: наибольшее 5/4 при x = −2, наименьшее f(0) = 1 достигается (было «наименьшего нет»); вариант «5/4; 1» равен ответу — закрыт"}
P["G11_TB_13_4*_13_23_б"] = {"q": r"Решите уравнение: $\dfrac{\cos^{2} 2x}{\sin^{8} x} + \dfrac{\sin^{8} x}{\cos^{2} 2x} = 2 \cos^{2} \sqrt{\dfrac{\pi^{2}}{4} - x^{2}}$", "src": SRC,
  "why": QG + "дроби cos²2x/sin⁸x и sin⁸x/cos²2x были переписаны как cos²(2x/sin⁸x) и sin⁸(x/cos²2x) (№ 13.23 б); ключ ±π/2 верен"}
P["G11_TB_5_2_5_17_2"] = {"qrep": (r"n^{2} - 40$, $5n + 305", r"n^{2} - 40{,}5n + 305"), "src": SRC, "why": QG + "коэффициент 40,5 был разорван на «40» и «5n» (№ 5.17 б); ключ −105 верен"}
P["G11_TB_5_2_5_17_1"] = {"qrep": (r"n^{2} - 30$, $5n + 205", r"n^{2} - 30{,}5n + 205"), "src": SRC, "why": QG + "коэффициент 30,5 был разорван на «30» и «5n» (№ 5.17 а); ключ −27,5 верен"}
